-- Governed encrypted content artifacts; no parent data mutation or access restoration.
BEGIN;
DO $$ BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_lifecycle_operation_config(text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM 'b8ba88118ffab593ad87cc4c625f35c73d2882b81e4568354af3d2a60ea65ecc' THEN RAISE EXCEPTION 'tenant_content_prior_dispatch_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_lifecycle_operation_config(p_operation text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT $config${"supabase.tenant.export":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"export"},"supabase.tenant.manifests.export":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"export"},"supabase.tenant.erase":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"erase"},"supabase.tenant.manifests.erase":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"erase"},"supabase.tenant.restore":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"restore"},"supabase.tenant.manifests.restore":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"restore"},"supabase.tenant.exports.get":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"get"},"supabase.tenant.manifests.exports.get":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"get"},"supabase.tenant.exports.purge":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"purge"},"supabase.tenant.manifests.exports.purge":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"purge"},"supabase.tenant.protected_resources.inventory":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"inventory"},"supabase.tenant.content.export":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"content_export"},"supabase.tenant.content.exports.get":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"content_get"},"supabase.tenant.content.exports.purge":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"purge"}}$config$::jsonb->p_operation
$$;
DO $$ BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_manifest_resolve(text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '1483bdd708b7ce71f6fa9d3c61920f33e95310bed02726eacdab08cda8763896' THEN RAISE EXCEPTION 'tenant_content_prior_dispatch_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_manifest_resolve(p_manifest text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF p_manifest='application_leaf_links_v1' THEN RETURN public.sandy_tenant_manifest_v1();
 ELSIF p_manifest='application_scalar_links_v1' THEN RETURN public.sandy_tenant_manifest_scalar_v1();
 ELSIF p_manifest='customer_content_fragments_v1' THEN RETURN public.sandy_tenant_content_manifest_v1();
 ELSE RAISE EXCEPTION 'tenant_manifest_not_supported';END IF;
END $$;
CREATE TABLE public.sandy_tenant_content_snapshots(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 manifest_sha256 text NOT NULL,schema_sha256 text NOT NULL,fragment_count integer NOT NULL CHECK(fragment_count BETWEEN 1 AND 2048),row_counts jsonb NOT NULL,total_plaintext_bytes bigint NOT NULL CHECK(total_plaintext_bytes BETWEEN 0 AND 134217728),artifact_index_sha256 text NOT NULL,
 state text NOT NULL DEFAULT 'exported' CHECK(state IN('exported','purged')),source_admission_id uuid NOT NULL UNIQUE REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL
);
CREATE TABLE public.sandy_tenant_content_fragments(
 snapshot_id uuid NOT NULL REFERENCES public.sandy_tenant_content_snapshots(id) ON DELETE RESTRICT,sequence integer NOT NULL CHECK(sequence BETWEEN 0 AND 2047),artifact_sha256 text NOT NULL,vault_secret_id uuid,table_name text NOT NULL,artifact_bytes integer NOT NULL CHECK(artifact_bytes BETWEEN 1 AND 1048576),PRIMARY KEY(snapshot_id,sequence)
);
CREATE TABLE public.sandy_tenant_content_receipts(admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,snapshot_id uuid NOT NULL REFERENCES public.sandy_tenant_content_snapshots(id) ON DELETE RESTRICT,result jsonb NOT NULL);
CREATE TRIGGER sandy_tenant_content_receipts_immutable BEFORE UPDATE OR DELETE ON public.sandy_tenant_content_receipts FOR EACH ROW EXECUTE FUNCTION public.sandy_tenant_lifecycle_immutable();
ALTER TABLE public.sandy_tenant_content_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_tenant_content_fragments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_tenant_content_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sandy_tenant_content_snapshots,public.sandy_tenant_content_fragments,public.sandy_tenant_content_receipts FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.sandy_tenant_content_metadata(p_snapshot public.sandy_tenant_content_snapshots) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
 SELECT jsonb_build_object('snapshot_id',(p_snapshot).id,'tenant_id',(p_snapshot).tenant_id,'manifest','customer_content_fragments_v1','manifest_sha256',(p_snapshot).manifest_sha256,'schema_sha256',(p_snapshot).schema_sha256,'fragment_count',(p_snapshot).fragment_count,'row_counts',(p_snapshot).row_counts,'total_plaintext_bytes',(p_snapshot).total_plaintext_bytes,'artifact_index_sha256',(p_snapshot).artifact_index_sha256,'state',(p_snapshot).state,'created_at',(p_snapshot).created_at,'expires_at',(p_snapshot).expires_at,'complete_tenant_coverage',false,'external_provider_assets_included',false,'erasure_supported',false,'restore_supported',false)
$$;
CREATE FUNCTION public.sandy_tenant_content_execute(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
DECLARE ctx jsonb;args jsonb;tenant uuid;op text;manifest jsonb:=public.sandy_tenant_content_manifest_v1();snapshot public.sandy_tenant_content_snapshots;fragment jsonb;fragment_row public.sandy_tenant_content_fragments;material text;vault_id uuid;index_data jsonb:='[]';index_sha text;counts jsonb:='{}';total_bytes bigint:=0;fragment_count integer:=0;snapshot_id uuid;result jsonb;previous jsonb;
BEGIN
 ctx:=public.sandy_tenant_lifecycle_context(p_actor,p_admission,p_canonical);args:=ctx->'arguments';tenant:=(ctx->>'tenant_id')::uuid;op:=ctx->>'operation';
 IF op NOT IN('supabase.tenant.content.export','supabase.tenant.content.exports.get','supabase.tenant.content.exports.purge') OR ctx->>'manifest' IS DISTINCT FROM manifest->>'id' THEN RAISE EXCEPTION 'tenant_content_operation_not_supported';END IF;
 SELECT receipt.result INTO previous FROM public.sandy_tenant_content_receipts receipt WHERE receipt.admission_id=p_admission;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'result',previous,'reused',true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('tenant_manifest_lifecycle:'||tenant::text,0));
 IF op='supabase.tenant.content.export' THEN
  snapshot_id:=gen_random_uuid();
  -- The STABLE capture SELECT uses one database statement snapshot for every
  -- source row/table while this outer function encrypts each bounded fragment.
  FOR fragment IN SELECT * FROM public.sandy_tenant_content_capture_v1(tenant) LOOP
   IF (fragment->>'sequence')::integer<>fragment_count OR fragment->>'tenant_id' IS DISTINCT FROM tenant::text OR fragment->>'manifest_sha256' IS DISTINCT FROM manifest->>'manifest_sha256' THEN RAISE EXCEPTION 'tenant_content_fragment_scope_failed';END IF;
   fragment:=fragment||jsonb_build_object('snapshot_id',snapshot_id,'schema_sha256',manifest->>'schema_sha256','complete_tenant_coverage',false,'external_provider_assets_included',false);
   material:=fragment::text;
   IF octet_length(material)>1048576 THEN RAISE EXCEPTION 'tenant_content_fragment_artifact_bound_exceeded';END IF;
   total_bytes:=total_bytes+octet_length(fragment->>'json_fragment');
   IF total_bytes>134217728 OR fragment_count>=2048 THEN RAISE EXCEPTION 'tenant_content_snapshot_bound_exceeded';END IF;
   SELECT vault.create_secret(material,'sandy_tenant_content_v1_'||snapshot_id::text||'_'||fragment_count::text,'Private typed customer-content fragment') INTO vault_id;
   IF NOT EXISTS(SELECT 1 FROM vault.decrypted_secrets WHERE id=vault_id AND decrypted_secret=material) THEN RAISE EXCEPTION 'tenant_content_fragment_encryption_readback_failed';END IF;
   index_data:=index_data||jsonb_build_array(jsonb_build_object('sequence',fragment_count,'table',fragment->>'table','artifact_sha256',encode(extensions.digest(material,'sha256'),'hex'),'artifact_bytes',octet_length(material),'vault_secret_id',vault_id));
   IF (fragment->>'table_complete')::boolean THEN counts:=counts||jsonb_build_object(fragment->>'table',(fragment->>'table_row_count')::integer);END IF;
   fragment_count:=fragment_count+1;
  END LOOP;
  IF fragment_count=0 OR (SELECT count(*) FROM jsonb_object_keys(counts))<>20 THEN RAISE EXCEPTION 'tenant_content_capture_incomplete';END IF;
  -- Public index digest omits custody references and binds only safe sequence,
  -- table, byte count and exact canonical-artifact SHA-256 metadata.
  SELECT encode(extensions.digest(jsonb_agg(e.value-'vault_secret_id' ORDER BY (e.value->>'sequence')::integer)::text,'sha256'),'hex') INTO index_sha FROM jsonb_array_elements(index_data)e(value);
  INSERT INTO public.sandy_tenant_content_snapshots(id,tenant_id,manifest_sha256,schema_sha256,fragment_count,row_counts,total_plaintext_bytes,artifact_index_sha256,source_admission_id,expires_at) VALUES(snapshot_id,tenant,manifest->>'manifest_sha256',manifest->>'schema_sha256',fragment_count,counts,total_bytes,index_sha,p_admission,clock_timestamp()+interval '24 hours') RETURNING * INTO snapshot;
  INSERT INTO public.sandy_tenant_content_fragments(snapshot_id,sequence,artifact_sha256,vault_secret_id,table_name,artifact_bytes) SELECT snapshot_id,(e->>'sequence')::integer,e->>'artifact_sha256',(e->>'vault_secret_id')::uuid,e->>'table',(e->>'artifact_bytes')::integer FROM jsonb_array_elements(index_data)e;
 ELSE
  SELECT * INTO snapshot FROM public.sandy_tenant_content_snapshots WHERE id=(args->>'snapshot_id')::uuid AND tenant_id=tenant FOR UPDATE;
  IF snapshot.id IS NULL THEN RAISE EXCEPTION 'tenant_content_snapshot_not_found';END IF;
  IF snapshot.manifest_sha256 IS DISTINCT FROM manifest->>'manifest_sha256' OR snapshot.schema_sha256 IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_content_snapshot_manifest_unsupported';END IF;
  IF op='supabase.tenant.content.exports.purge' THEN
   IF args->>'confirm_artifact_purge' IS DISTINCT FROM 'true' OR snapshot.state='purged' THEN RAISE EXCEPTION 'tenant_content_purge_refused';END IF;
   FOR fragment_row IN SELECT * FROM public.sandy_tenant_content_fragments WHERE sandy_tenant_content_fragments.snapshot_id=snapshot.id FOR UPDATE LOOP
    IF fragment_row.vault_secret_id IS NULL OR EXISTS(SELECT 1 FROM public.sandy_credential_versions WHERE vault_secret_id=fragment_row.vault_secret_id) THEN RAISE EXCEPTION 'tenant_content_purge_custody_refused';END IF;
    DELETE FROM vault.secrets WHERE id=fragment_row.vault_secret_id AND name='sandy_tenant_content_v1_'||snapshot.id::text||'_'||fragment_row.sequence::text;
    IF NOT FOUND OR EXISTS(SELECT 1 FROM vault.secrets WHERE id=fragment_row.vault_secret_id) THEN RAISE EXCEPTION 'tenant_content_purge_readback_failed';END IF;
   END LOOP;
   UPDATE public.sandy_tenant_content_fragments SET vault_secret_id=NULL WHERE sandy_tenant_content_fragments.snapshot_id=snapshot.id;
   UPDATE public.sandy_tenant_content_snapshots SET state='purged' WHERE id=snapshot.id RETURNING * INTO snapshot;
  END IF;
 END IF;
 result:=public.sandy_tenant_content_metadata(snapshot);
 INSERT INTO public.sandy_tenant_content_receipts(admission_id,snapshot_id,result) VALUES(p_admission,snapshot.id,result);
 INSERT INTO public.sandy_tenant_lifecycle_events(tenant_id,snapshot_id,actor_id,admission_id,operation,before_sha256,after_sha256) VALUES(tenant,snapshot.id,p_actor,p_admission,op,snapshot.artifact_index_sha256,snapshot.artifact_index_sha256);
 RETURN jsonb_build_object('ok',true,'result',result,'reused',false);
END $$;
CREATE FUNCTION public.sandy_tenant_content_fragment_download(p_snapshot uuid,p_sequence integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant uuid:=public.sandy_supabase_portal_tenant(auth.uid());snapshot public.sandy_tenant_content_snapshots;fragment public.sandy_tenant_content_fragments;material text;payload jsonb;
BEGIN
 IF tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'http_status',403);END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation='supabase.tenant.content.exports.download' AND handler='sandy-operation-api' AND api_exposed AND verified AND error_contract->>'requires_real_user_session'='true') THEN RETURN jsonb_build_object('ok',false,'http_status',424);END IF;
 IF p_sequence IS NULL OR p_sequence<0 OR p_sequence>=2048 THEN RETURN jsonb_build_object('ok',false,'http_status',404);END IF;
 SELECT * INTO snapshot FROM public.sandy_tenant_content_snapshots WHERE id=p_snapshot AND tenant_id=tenant FOR SHARE;
 IF snapshot.id IS NULL THEN RETURN jsonb_build_object('ok',false,'http_status',404);END IF;
 IF snapshot.expires_at<=clock_timestamp() OR snapshot.state='purged' THEN RETURN jsonb_build_object('ok',false,'http_status',410);END IF;
 IF snapshot.manifest_sha256 IS DISTINCT FROM public.sandy_tenant_content_manifest_v1()->>'manifest_sha256' OR snapshot.schema_sha256 IS DISTINCT FROM public.sandy_tenant_content_manifest_v1()->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_content_snapshot_manifest_unsupported';END IF;
 SELECT * INTO fragment FROM public.sandy_tenant_content_fragments WHERE snapshot_id=p_snapshot AND sequence=p_sequence FOR SHARE;
 IF fragment.snapshot_id IS NULL OR fragment.vault_secret_id IS NULL THEN RETURN jsonb_build_object('ok',false,'http_status',404);END IF;
 SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=fragment.vault_secret_id AND name='sandy_tenant_content_v1_'||p_snapshot::text||'_'||p_sequence::text;
 IF material IS NULL OR octet_length(material)>1048576 OR encode(extensions.digest(material,'sha256'),'hex') IS DISTINCT FROM fragment.artifact_sha256 THEN RAISE EXCEPTION 'tenant_content_fragment_integrity_failed';END IF;
 payload:=material::jsonb;
 IF payload->>'tenant_id' IS DISTINCT FROM tenant::text OR payload->>'snapshot_id' IS DISTINCT FROM p_snapshot::text OR payload->>'sequence' IS DISTINCT FROM p_sequence::text THEN RAISE EXCEPTION 'tenant_content_fragment_scope_failed';END IF;
 INSERT INTO public.sandy_tenant_lifecycle_events(tenant_id,snapshot_id,actor_id,operation,before_sha256,after_sha256) VALUES(tenant,p_snapshot,auth.uid(),'supabase.tenant.content.exports.download',fragment.artifact_sha256,fragment.artifact_sha256);
 RETURN jsonb_build_object('ok',true,'snapshot_id',p_snapshot,'sequence',p_sequence,'artifact_sha256',fragment.artifact_sha256,'artifact_json',material);
END $$;
REVOKE ALL ON FUNCTION public.sandy_tenant_content_metadata(public.sandy_tenant_content_snapshots),public.sandy_tenant_content_execute(uuid,uuid,text),public.sandy_tenant_content_fragment_download(uuid,integer) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_tenant_content_execute(uuid,uuid,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.sandy_tenant_content_fragment_download(uuid,integer) TO authenticated;
DO $contracts$ DECLARE contract jsonb;BEGIN
 contract:=$c${"operation":"supabase.tenant.content.export","handler":"sandy-tenant-lifecycle-api","permission_scope":"infrastructure:write","is_mutation":true,"requires_grant":true,"requires_cost_approval":false,"requirement":111,"input_schema":{"type":"object","properties":{"tenant_id":{"type":"string","format":"uuid"},"manifest":{"const":"customer_content_fragments_v1"},"expected_manifest_sha256":{"const":"3c52f9ea5c2726ec7a82aeec1e9f1fadf796dc8bf35127f368a762bf823e0d99"}},"required":["tenant_id","manifest","expected_manifest_sha256"],"additionalProperties":false},"result_schema":{"type":"object","properties":{"snapshot_id":{"type":"string","format":"uuid"},"tenant_id":{"type":"string","format":"uuid"},"manifest":{"const":"customer_content_fragments_v1"},"manifest_sha256":{"const":"3c52f9ea5c2726ec7a82aeec1e9f1fadf796dc8bf35127f368a762bf823e0d99"},"schema_sha256":{"const":"35291441439bfe3286bf362a69b7ac91482437ecd50a2c72d7cf8e1bb5f54b6e"},"fragment_count":{"type":"integer","minimum":1,"maximum":2048},"row_counts":{"type":"object","properties":{"email_customers":{"type":"integer","minimum":0,"maximum":50000},"email_customer_addresses":{"type":"integer","minimum":0,"maximum":50000},"sandy_people":{"type":"integer","minimum":0,"maximum":50000},"sandy_social_people":{"type":"integer","minimum":0,"maximum":50000},"sandy_tasks":{"type":"integer","minimum":0,"maximum":50000},"sandy_agenda_companies":{"type":"integer","minimum":0,"maximum":50000},"sandy_life_spaces":{"type":"integer","minimum":0,"maximum":50000},"sandy_life_goals":{"type":"integer","minimum":0,"maximum":50000},"sandy_knowledge_documents":{"type":"integer","minimum":0,"maximum":50000},"sandy_knowledge_entities":{"type":"integer","minimum":0,"maximum":50000},"email_conversations":{"type":"integer","minimum":0,"maximum":50000},"email_messages":{"type":"integer","minimum":0,"maximum":50000},"sandy_product_support_cases":{"type":"integer","minimum":0,"maximum":50000},"sandy_product_support_comments":{"type":"