CREATE FUNCTION public.sandy_tenant_content_exports_available(p_offset integer,p_limit integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant uuid:=public.sandy_supabase_portal_tenant(auth.uid());total bigint;items jsonb;
BEGIN
 IF tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'http_status',403);END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation='supabase.tenant.content.exports.available' AND handler='sandy-operation-api' AND api_exposed AND verified AND error_contract->>'requires_real_user_session'='true') THEN RETURN jsonb_build_object('ok',false,'http_status',424);END IF;
 IF p_offset IS NULL OR p_offset<0 OR p_offset>2147483000 OR p_limit IS NULL OR p_limit<1 OR p_limit>50 THEN RAISE EXCEPTION 'tenant_content_pagination_invalid';END IF;
 SELECT count(*) INTO total FROM public.sandy_tenant_content_snapshots WHERE tenant_id=tenant;
 IF total>2147483647 THEN RAISE EXCEPTION 'tenant_content_pagination_bound_exceeded';END IF;
 SELECT coalesce(jsonb_agg(public.sandy_tenant_content_metadata(page.snapshot) ORDER BY (page.snapshot).created_at DESC,(page.snapshot).id DESC),'[]'::jsonb) INTO items FROM(SELECT s AS snapshot FROM public.sandy_tenant_content_snapshots s WHERE s.tenant_id=tenant ORDER BY s.created_at DESC,s.id DESC LIMIT p_limit OFFSET p_offset)page;
 RETURN jsonb_build_object('ok',true,'offset',p_offset,'limit',p_limit,'total_count',total,'next_offset',CASE WHEN p_offset+jsonb_array_length(items)<total THEN p_offset+jsonb_array_length(items) ELSE NULL END,'items',items);
END $$;
